sys_ui_action.client_script_v2:
function onClick(g_form) {
    var api = 'x_fub_fundbrad_ev.EvPendenteAjax';
    var recordId = g_form.getUniqueValue();

    function parseResponse(answer) {
        var response;

        try {
            response = JSON.parse(answer || '{}');
        } catch (error) {
            response = { error: 'Resposta inválida do servidor.' };
        }

        if (!response || response.success !== true) {
            g_form.addErrorMessage(
                (response && response.error) || 'Não foi possível executar a ação.'
            );
            return null;
        }

        return response;
    }

    var ga = new GlideAjax(api);
    ga.addParam('sysparm_name', 'opcoes');
    ga.addParam('sysparm_record_id', recordId);

    ga.getXMLAnswer(function(answer) {
        var response = parseResponse(answer);
        if (!response) return;

        g_modal.showFields({
            title: 'Pendente',
            instruction: 'Selecione o motivo da pendência.',
            fields: [{
                type: 'choice',
                name: 'reason',
                label: 'Motivo da pendência',
                mandatory: true,
                choices: [{ value: '', displayValue: '-- Selecione --' }]
                    .concat(response.choices || [])
            }],
            size: 'lg'
        }).then(function(result) {
            if (!result) return;

            var reason = '';

            (result.updatedFields || []).forEach(function(field) {
                if (field.name === 'reason') {
                    reason = String(field.value || '').trim();
                }
            });

            if (!reason) {
                g_form.addErrorMessage('Selecione o motivo da pendência.');
                return;
            }

            var request = new GlideAjax(api);
            request.addParam('sysparm_name', 'pendenciar');
            request.addParam('sysparm_record_id', recordId);
            request.addParam('sysparm_reason', reason);

            request.getXMLAnswer(function(answer) {
                if (!parseResponse(answer)) return;

                g_form.addInfoMessage('Atendimento alterado para Pendente.');
                g_form.reload();
            });
        }, function() {
            // Modal cancelado.
        });
    });
}

sys_ui_action.script:
function pendenciarAtendimento() {
    var dialog = new GlideModal('x_fub_fundbrad_ev_ev_pendente_modal');

    dialog.setTitle('Pendente');
    dialog.setPreference('sysparm_record_id', g_form.getUniqueValue());
    dialog.setWidth(600);
    dialog.render();

    return false;
}
